(() => {
'use strict';
const $=s=>document.querySelector(s), vocab=window.VOCAB;
const canvas=$('#board'),ctx=canvas.getContext('2d');
const path=[];for(let x=0;x<12;x++)path.push([x,0]);for(let z=0;z<12;z++)path.push([12,z]);for(let x=12;x>0;x--)path.push([x,12]);for(let z=12;z>0;z--)path.push([0,z]);
let pos=0,coins=0,round=1,owned=new Set(),phase='ready',choices=[],correctIndex=-1,player=[0,0],hop=0,epoch=0,lastRoll=0;
let width=0,height=0,unit=1,ox=0,oy=0;
const shades=['#c5b5e1','#b6d5cd','#efc6b7','#ecd5a6'];
const random=n=>{const a=new Uint32Array(1);const limit=Math.floor(4294967296/n)*n;do{crypto.getRandomValues(a)}while(a[0]>=limit);return a[0]%n};
function shuffle(a){for(let i=a.length-1;i>0;i--){let j=random(i+1);[a[i],a[j]]=[a[j],a[i]]}return a}
function project(x,z,y=0){return [ox+(x-z)*unit,oy+(x+z)*unit*.51-y*unit]}
function polygon(points,color,stroke){ctx.beginPath();points.forEach((p,i)=>{const q=project(...p);i?ctx.lineTo(...q):ctx.moveTo(...q)});ctx.closePath();ctx.fillStyle=color;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=.7;ctx.stroke()}}
function box(x,z,y,w,d,h,top,left,right){polygon([[x,z,y+h],[x+w,z,y+h],[x+w,z+d,y+h],[x,z+d,y+h]],top);polygon([[x,z+d,y],[x+w,z+d,y],[x+w,z+d,y+h],[x,z+d,y+h]],left);polygon([[x+w,z,y],[x+w,z+d,y],[x+w,z+d,y+h],[x+w,z,y+h]],right)}
function tree(x,z,s=1){box(x-.08,z-.08,.08,.16,.16,.6*s,'#b49a86','#b49a86','#987f6c');let y=.5;for(let i=0;i<2;i++){let r=(.5-i*.13)*s;polygon([[x-r,z-r,y],[x+r,z-r,y],[x,z,y+1*s]],'#9fc6ac');polygon([[x+r,z-r,y],[x+r,z+r,y],[x,z,y+1*s]],'#75ac91');polygon([[x+r,z+r,y],[x-r,z+r,y],[x,z,y+1*s]],'#87bba0');y+=.5*s}}
function house(x,z,s=1,color='#d8b7ca'){box(x,z,.06,s,s,s*.7,'#f7ebd7','#f6e6cf','#deceb9');polygon([[x-.1,z-.1,.7*s],[x+s+.1,z-.1,.7*s],[x+s/2,z-.1,1.25*s]],color);polygon([[x+s+.1,z-.1,.7*s],[x+s+.1,z+s+.1,.7*s],[x+s/2,z+s+.1,1.25*s],[x+s/2,z-.1,1.25*s]],'#ab88b4');polygon([[x-.1,z-.1,.7*s],[x+s/2,z-.1,1.25*s],[x+s/2,z+s+.1,1.25*s],[x-.1,z+s+.1,.7*s]],color);box(x+s*.36,z+s+.005,.06,s*.26,.01,s*.4,'#a88d84','#a88d84','#a88d84')}
function cat(){let [x,z]=player;x+=.22;z+=.22;const y=.5+hop;box(x,z,y,.54,.54,.57,'#fff2d9','#f4d8b1','#e9c699');box(x-.02,z-.02,y+.5,.58,.55,.46,'#fff5e0','#f6dfbc','#efd1a9');polygon([[x,z,y+.96],[x+.19,z,y+.96],[x,z,y+1.22]],'#e4bcac');polygon([[x+.36,z,y+.96],[x+.56,z,y+.96],[x+.56,z,y+1.22]],'#e4bcac');const face=project(x+.24,z+.56,y+.75);ctx.fillStyle='#68505a';ctx.beginPath();ctx.arc(face[0]-unit*.12,face[1],unit*.033,0,Math.PI*2);ctx.arc(face[0]+unit*.1,face[1]-unit*.10,unit*.033,0,Math.PI*2);ctx.fill();box(x-.1,z+.32,y+.1,.16,.15,.42,'#bea6e0','#aa8bcf','#9676b9');const a=project(x+.25,z+.2,y+1.65);ctx.fillStyle='#8d72cf';ctx.font=`bold ${Math.max(11,unit*.39)}px Segoe UI`;ctx.textAlign='center';ctx.fillText('MISO',a[0],a[1])}
function draw(){ctx.clearRect(0,0,width,height);ctx.save();const p=project(6,6,-1.1);ctx.fillStyle='#a8b3bc25';ctx.beginPath();ctx.ellipse(p[0],p[1],unit*12.9,unit*6.3,0,0,Math.PI*2);ctx.fill();box(-.35,-.35,-.65,13.7,13.7,.6,'#deead7','#bccab8','#a6bdae');box(1.12,1.12,-.05,10.76,10.76,.13,'#d8e8ce','#c6d8bf','#bad0b2');
path.forEach(([x,z],i)=>{const color=i===0?'#efd396':owned.has(i)?'#9ad4b7':shades[Math.floor(i/12)];box(x+.035,z+.035,0,.93,.93,.28,color,'#b9adca','#a99bbd');box(x+.09,z+.09,.28,.82,.82,.045,i===0?'#ffe8b4':owned.has(i)?'#c2ead5':'#f8f5ed','#e5e0d9','#e0d9cf');box(x+.09,z+.09,.328,.82,.18,.02,color,color,color);const p=project(x+.51,z+.62,.35);ctx.textAlign='center';ctx.fillStyle=i===pos?'#7156af':'#9a8baa';ctx.font=`700 ${Math.max(8,unit*.30)}px Segoe UI`;ctx.fillText(i===0?'GO':String(i).padStart(2,'0'),p[0],p[1]);if(i===pos){ctx.strokeStyle='#9772ce';ctx.lineWidth=2;ctx.beginPath();[[x,z,.36],[x+1,z,.36],[x+1,z+1,.36],[x,z+1,.36]].forEach((a,j)=>{const q=project(...a);j?ctx.lineTo(...q):ctx.moveTo(...q)});ctx.closePath();ctx.stroke()}if(owned.has(i)){const q=project(x+.73,z+.75,.45);ctx.fillStyle='#4d9474';ctx.font=`bold ${Math.max(9,unit*.4)}px Segoe UI`;ctx.fillText('⚑',q[0],q[1])}});
// Faceted town center, a pond and little trees, all drawn in 3D coordinates.
polygon([[3,4,.1],[4,3.8,.1],[5.2,4.4,.1],[5.5,5.6,.1],[4.3,6.1,.1],[2.8,5.5,.1]],'#a9d6d3');polygon([[3.3,4.4,.11],[4.2,4.15,.11],[4.9,4.5,.11],[4.6,5.1,.11],[3.4,5.2,.11]],'#bde5de');
const objects=[{x:6.8,z:3.2,f:()=>house(6.8,3.2,1.5,'#d6a5ad')},{x:8.4,z:5.2,f:()=>house(8.4,5.2,1,'#b2a4d7')}];
[[2.1,2.4,1],[4,2,.7],[9.8,2.3,1.1],[10.3,7.3,1],[2.3,7.8,1.1],[3.4,9.8,.8],[8,9.9,.9],[10.4,10.3,.7]].forEach(([x,z,s])=>objects.push({x,z,f:()=>tree(x,z,s)}));objects.push({x:player[0],z:player[1],f:cat});objects.sort((a,b)=>a.x+a.z-b.x-b.z).forEach(o=>o.f());
const title=project(6.1,7.5,.15);ctx.save();ctx.translate(...title);ctx.rotate(-.02);ctx.textAlign='center';ctx.fillStyle='#91a58b';ctx.font=`800 ${unit*.68}px Segoe UI`;ctx.fillText('VOCAB ISLAND',0,0);ctx.font=`600 ${unit*.29}px Segoe UI`;ctx.fillStyle='#a0b199';ctx.fillText('LEARN • EXPLORE • GROW',0,unit*.5);ctx.restore();ctx.restore()}
function resize(){const rect=canvas.getBoundingClientRect();width=rect.width;height=rect.height;canvas.width=width*devicePixelRatio;canvas.height=height*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);unit=Math.min((width-50)/27,(height-225)/15);ox=width/2;oy=Math.max(180,(height-unit*13)/2+38);draw()}
new ResizeObserver(resize).observe(canvas);
canvas.addEventListener('pointermove',e=>{const rect=canvas.getBoundingClientRect();const dx=(e.clientX-rect.left-ox)/unit;const dz=(e.clientY-rect.top-oy+unit*.35)/(unit*.51);const x=Math.floor((dx+dz)/2),z=Math.floor((dz-dx)/2);const i=path.findIndex(p=>p[0]===x&&p[1]===z);$('.map-hint').textContent=i>0?'Ô '+i+' · '+vocab[i-1].term:i===0?'GO · Đi qua xuất phát nhận 200 xu':'Chạm hoặc rê chuột lên ô để xem từ vựng';});
function update(){ $('#coins').textContent=coins.toLocaleString('vi-VN');$('#owned').textContent=owned.size;$('#round').textContent=round;$('#progress-label').textContent=`${owned.size} / 47`;$('#progress').style.width=`${owned.size/47*100}%`;if(owned.size===47)$('#encouragement').textContent='Tuyệt vời! Bạn đã chinh phục cả 47 từ.';draw()}
const delay=ms=>new Promise(r=>setTimeout(r,ms));
async function roll(){if(phase!=='ready')return;phase='moving';const token=epoch;$('#roll').disabled=true;$('#phase').textContent='XÚC XẮC ĐANG LĂN';const dice=$('#dice');dice.classList.add('rolling');lastRoll=random(6)+1;for(let i=0;i<10;i++){dice.textContent=['⚀','⚁','⚂','⚃','⚄','⚅'][random(6)];await delay(65);if(epoch!==token)return}dice.classList.remove('rolling');dice.textContent=['⚀','⚁','⚂','⚃','⚄','⚅'][lastRoll-1];$('#phase').textContent=`ĐI ${lastRoll} BƯỚC`;for(let i=0;i<lastRoll;i++){let old=path[pos];pos=(pos+1)%48;if(pos===0){coins+=200;round++}const dest=path[pos];let start=performance.now();await new Promise(resolve=>{function frame(now){if(token!==epoch){resolve();return}let t=Math.min(1,(now-start)/220);player=[old[0]+(dest[0]-old[0])*t,old[1]+(dest[1]-old[1])*t];hop=Math.sin(t*Math.PI)*.65;draw();if(t<1)requestAnimationFrame(frame);else resolve()}requestAnimationFrame(frame)});if(token!==epoch)return}hop=0;update();if(pos===0){phase='result';$('#content').innerHTML='<div class="question-emoji">🎉</div><h2>Một vòng khám phá!</h2><p>Bạn nhận 200 xu khi đi qua xuất phát.</p>';$('#roll').classList.add('hidden');$('#next').classList.remove('hidden');$('#phase').textContent='CHÀO MỪNG TRỞ LẠI';$('#tile-tag').textContent='Ô xuất phát'}else question()}
function question(){phase='question';const item=vocab[pos-1];const wrong=shuffle([...new Set(vocab.filter(v=>v.meaning!==item.meaning).map(v=>v.meaning))]).slice(0,2);choices=shuffle([item.meaning,...wrong]);correctIndex=choices.indexOf(item.meaning);$('#phase').textContent='TỪ NÀY CÓ NGHĨA LÀ GÌ?';$('#tile-tag').textContent=`Ô ${pos} · Lắc ${lastRoll}`;$('#content').replaceChildren();const icon=document.createElement('div');icon.className='question-emoji';icon.textContent='🏡';const h=document.createElement('h2');h.textContent=item.term;const p=document.createElement('p');p.textContent='Chọn nghĩa tiếng Việt chính xác';$('#content').append(icon,h,p);$('#roll').classList.add('hidden');$('#answers').replaceChildren();choices.forEach((s,i)=>{const b=document.createElement('button');b.className='answer';const n=document.createElement('b');n.textContent=String(i+1);const t=document.createElement('span');t.textContent=s;b.append(n,t);b.onclick=()=>answer(i);$('#answers').append(b)});$('#answers button').focus();$('#keyhint').textContent='Chọn đáp án bằng phím 1, 2 hoặc 3'}
function answer(i){if(phase!=='question'||!Number.isInteger(i)||i<0||i>2)return;phase='result';const correct=i===correctIndex;const item=vocab[pos-1];if(correct){coins+=100;owned.add(pos)}[...$('#answers').children].forEach((b,j)=>{b.disabled=true;if(j===correctIndex)b.classList.add('correct');else if(j===i)b.classList.add('wrong')});const p=document.createElement('p');p.className='result';p.textContent=correct?'Chính xác! +100 xu · Ô đất thuộc về bạn.':'Chưa đúng rồi. Đáp án: '+item.meaning;const def=document.createElement('p');def.className='definition';def.textContent=item.definition;$('#content').append(p,def);$('#phase').textContent=correct?'GIỎI LẮM, NHÀ THÁM HIỂM!':'THÊM MỘT ĐIỀU VỪA HỌC';$('#next').classList.remove('hidden');$('#keyhint').textContent='Nhấn Enter để tiếp tục';update();if(owned.size===47){$('#phase').textContent='BẠN ĐÃ CHINH PHỤC HÒN ĐẢO!'}$('#next').focus()}
function ready(){phase='ready';$('#content').innerHTML='<div class="dice" id="dice">⚄</div><h2>Chuyến đi tiếp theo?</h2><p>Lắc xúc xắc để khám phá thêm một từ mới.</p>';$('#answers').replaceChildren();$('#roll').classList.remove('hidden');$('#roll').disabled=false;$('#next').classList.add('hidden');$('#phase').textContent='SẴN SÀNG LÊN ĐƯỜNG';$('#keyhint').textContent='Nhấn Space để lắc · 1–3 để chọn';$('#roll').focus()}
$('#roll').onclick=roll;$('#next').onclick=ready;$('#reset').onclick=()=>{if(!confirm('Bắt đầu lại? Xu và các ô đã sở hữu sẽ được đặt lại.'))return;epoch++;pos=0;coins=0;round=1;owned.clear();player=[0,0];hop=0;$('#tile-tag').textContent='Ô xuất phát';$('#encouragement').textContent='Hòn đảo lớn bắt đầu từ một bước nhỏ.';ready();update()};$('#help').onclick=()=>$('#help-dialog').showModal();$('#close-help').onclick=$('#start').onclick=()=>$('#help-dialog').close();document.addEventListener('keydown',e=>{if($('#help-dialog').open||e.repeat)return;if(e.code==='Space'&&phase==='ready'){e.preventDefault();roll()}else if(['1','2','3'].includes(e.key)&&phase==='question'){e.preventDefault();answer(Number(e.key)-1)}else if(e.key==='Enter'&&phase==='result'&&e.target!==$('#next')){e.preventDefault();ready()}});
window.vocabGame={getState:()=>({phase,position:pos,coins,round,owned:[...owned],lastRoll,term:pos?vocab[pos-1].term:null,options:phase==='question'?[...choices]:[]}),roll,answer};
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'roll_dice',description:'Roll the dice and move Miso 1 to 6 tiles when ready.',inputSchema:{type:'object',properties:{}},execute:async()=>{if(phase!=='ready')throw new Error('Finish the current turn first');await roll();return {content:[{type:'text',text:JSON.stringify(window.vocabGame.getState())}]}}});document.modelContext.registerTool({name:'answer_vocabulary',description:'Choose Vietnamese meaning option 1, 2 or 3 for the current word.',inputSchema:{type:'object',properties:{option:{type:'integer',minimum:1,maximum:3}},required:['option']},execute:async({option})=>{if(!Number.isInteger(option)||option<1||option>3||phase!=='question')throw new Error('Choose option 1 to 3 during a question');answer(option-1);return {content:[{type:'text',text:JSON.stringify(window.vocabGame.getState())}]}}})}catch(error){console.warn('Game tools unavailable',error)}}
resize();
})();
